from figures_plan2 import fig_slr, fig1, fig2, fig3, fig4, C1, C2, C3, CG

TITLE = '誰來賣、怎麼說、買了會不會退——AI 虛擬主播與真人主播的價值說服與購後後果：方法目的鏈、實驗設計與結構方程模式之二年期研究'

Y, N_, P = '✓', '—', '○'   # studied / not studied / partly studied

def build(d, refs):
    d.title(TITLE)
    # =====================================================================================
    d.h1('壹、研究計畫之背景及目的')
    d.h2('一、研究計畫之背景')
    d.p('直播帶貨已由「網紅即時叫賣」發展為結合即時互動、社群口碑與交易的成熟電商模式。直播能讓賣家以即時畫面與互動建立消費者信任 (Wongkitrungrueng & Assarut, 2020)，主播的外型示範與價值觀分享，則是降低產品不確定性、促成購買的訊號 (Lu & Chen, 2021)。頂級期刊的近期研究也開始以大規模平台資料檢驗直播的銷售機制，例如大、小網紅組合對產品銷售的影響 (Gu et al., 2024)。')
    d.p('**生成式 AI 讓「誰來賣」出現了新的選項：AI 虛擬主播。**AI 虛擬主播能大幅降低營運成本、大量產製直播內容，但也帶來智慧財產、錯誤資訊與消費者保護等治理問題 (Meng, 2026)。對資源有限的中小企業而言，AI 虛擬主播是一項低成本的替代方案；然而，它是否真的「賣得動」，現有證據並不一致。以天貓服飾零售商為對象的準實驗與田野實驗發現，現階段的數位主播與「不直播」相比並未顯著提高銷售，真人主播則有明顯效果；在數位主播加入即時問答等互動功能後，銷售才明顯提升 (Y. Liu et al., 2025)；然而，以美團外送直播的即時行為資料分析的研究卻發現，AI 主播的購買率高於真人主播，且語言情緒性與聲音變化越高，優勢越大 (Chen et al., 2026)。另一方面，Xiao et al. (2025) 發現相當比例的消費者對 AI 主播心存反感，反感來自擬人化與科技恐懼，並經由「不夠溫暖」與「不夠專業」兩條路徑形成；Chang et al. (2025) 則發現，消費者在 AI 主播的直播間更傾向尋找促銷資訊。')
    d.p('**然而，直播的成效不能只看「當下買不買」，還必須看「買了會不會退」。**Feng et al. (2025) 以直播電商平台資料比較即時直播與重播場次，發現即時互動帶來的說服效果會把消費者的購前期望推高到超過產品實際表現，使退貨率上升；依該研究的估計，互動強度每增加一個標準差，退貨率最多上升 11.68 個百分點。熱烈的直播氣氛雖然提高立即購買意圖，卻會經由資訊過載與期望落差降低購後滿意 (Fan et al., 2025)。值得注意的是，Wang et al. (2025) 在直播平台上進行隨機田野實驗，發現 AI 直播助理使銷售提高 3.00%、退貨率降低 12.55%，且效果在不確定性高的產品上較強。這意味著 AI 在直播中的價值，可能不只在於「多賣」，也在於「少退」。')
    d.p('行銷研究長期仰賴三種經典方法回答消費者行為問題：方法目的鏈（means-end chain, MEC）的階梯訪談、實驗設計與結構方程模式（structural equation modeling, SEM）。三者分別回答「為什麼」、「是否有因果」與「整條心理路徑是否成立」(Gutman, 1982; Wells & Windschitl, 1999; Anderson & Gerbing, 1988)。本計畫以這三種方法為主軸，針對 AI 虛擬主播與真人主播，回答三個環環相扣的問題：**消費者為什麼願意（或不願意）向 AI 主播購買？什麼樣的主播配上什麼樣的話術，能同時提高購買並降低後悔與退貨？這條從主播知覺到購後結果的路徑，在真實購物經驗中是否成立、對哪些消費者成立？**研究以運動鞋為錨定案例，美妝保養與居家家具為複製品類，且品類內同時有享樂型與實用型產品 (Dhar & Wertenbroch, 2000)。本計畫採「發現 → 檢驗 → 推廣」三階段設計，分二年進行，各階段的核心問題如下。')

    d.h4('第一階段：消費者為什麼向 AI 主播或真人主播購買？價值鏈的探索')
    d.q('消費者向 AI 虛擬主播與真人主播購買時，各自連結到哪些「屬性－後果－價值」？哪些價值鏈兩者共通、哪些各自特有？退貨與後悔位於價值鏈的哪個位置？')
    d.p('第一階段是本計畫的發現階段。現有 AI 主播研究多以問卷或情境實驗檢驗事先設定的構念，例如擬人化、社會臨場感與知覺價值 (Xiao et al., 2025; H. Liu et al., 2025)，較少回到消費者自己的語言，說明 AI 主播「為什麼」對他有意義。方法目的鏈理論認為，產品屬性經由使用後果連結到個人終極價值 (Gutman, 1982)，軟式階梯訪談能在不預設構念的情況下引出這些連結 (Reynolds & Gutman, 1988; Grunert & Grunert, 1995)。本階段以人工軟式階梯訪談比較兩類主播的購買者，並在後果層級系統性追問購買後的滿意、後悔與退貨。')
    d.p('本階段以方法目的鏈理論與消費價值理論為基礎。消費價值理論指出，消費選擇是功能、社會、情感、知識與情境等多元價值的函數 (Sheth et al., 1991)；方法目的鏈則說明這些價值如何經由具體屬性與後果被實現。直播購物的研究已顯示，實用、享樂與象徵價值會經由信任影響消費者的投入 (Wongkitrungrueng & Assarut, 2020)；本階段進一步追問：同樣的價值，經由 AI 主播與真人主播實現的路徑是否不同。')

    d.h4('第二階段：什麼樣的主播配上什麼樣的話術最有效？實驗設計的因果檢驗')
    d.q('主播類型（AI vs. 真人）與價值訴求話術（功能價值 vs. 情感社會價值）是否有交互作用？這個交互作用是否因產品類型而改變？AI 主播是否因為較低的說服意圖知覺而降低購後後悔與退貨？揭露 AI 身分的方式是否影響信任？')
    d.p('第二階段是本計畫的檢驗階段。消費者普遍認為 AI 較擅長實用性任務、較不擅長享樂性任務 (Longoni & Cian, 2022; Castelo et al., 2019)；人們也傾向以較具體的「怎麼做」層次理解 AI，因此 AI 傳遞具體訊息時較具說服力 (Kim & Duhachek, 2020)。直播情境的研究則發現，AI 主播搭配產品導向互動、真人主播搭配社交互動各有其適合的產品類型 (H. Liu et al., 2025)，AI 主播使用強勢訊息、真人主播使用非強勢訊息時，購買意圖較高 (Gong et al., 2025)。然而，這些研究的話術都由研究者事先設定，而非來自消費者的價值結構；依變數也多停留在購買意圖。')
    d.p('本階段採用社會知覺與說服知識理論為脈絡。Fiske et al. (2007) 指出，人們以溫暖與能力兩個基本向度評價他人；Lv et al. (2025) 則發現，AI 服務提供者常被知覺為較不溫暖。說服知識模型指出，消費者一旦察覺對方意圖說服，便會啟動因應與防衛 (Friestad & Wright, 1994)；而 AI 代理人被知覺為意圖較弱 (Garvey et al., 2023)。近期實驗已證實，在高強度說服情境下，消費者知覺 AI 主播的說服意圖低於真人主播，因而降低懷疑、提高購買意圖 (Lu & Li, 2026)。本階段把這個機制延伸到購後：AI 主播較低的說服意圖知覺，是否也使消費者較少因「被說服」而購買，進而降低購後後悔與退貨 (Feng et al., 2025; Tsiros & Mittal, 2000)，目前尚未被檢驗。')

    d.h4('第三階段：從主播知覺到購後結果的路徑在真實購物中是否成立？SEM 的推廣驗證')
    d.q('在真實的直播購物經驗中，主播的溫暖感與能力感如何經由信任、期望確認影響購後滿意、退貨與再購？這條路徑在 AI 主播與真人主播、在不同價值傾向的消費者之間是否相同？')
    d.p('第三階段是本計畫的推廣階段。實驗回答的是單一操弄的因果效果，但消費者從觀看直播到收貨、使用、決定是否退貨，是一段完整的心理歷程。期望確認理論指出，滿意取決於購前期望與實際表現的落差 (Oliver, 1980)；直播的高互動氣氛會提高購前期望，卻可能擴大期望落差 (Fan et al., 2025; Feng et al., 2025)。本階段以真實購買者的調查資料與三個月後的退貨追蹤，建構購後路徑模型，並以多群組 SEM 比較 AI 主播與真人主播購買者，以及第一階段界定的不同價值傾向消費者 (Cheung & Rensvold, 2002)。')

    d.p('三個階段以「價值」為線索串連：第一階段的價值鏈，在第二階段被改寫為實驗話術；第一階段發展的價值傾向量表，在第三階段成為多群組比較的分組依據。換言之，**本計畫以 MEC 回答「為什麼」、以實驗回答「是否有因果」、以 SEM 回答「在真實情境中對誰成立」**，三者互補，不需仰賴資料探勘即可回答「對誰有效」的問題。')

    d.h4('研究缺口')
    d.p('本計畫依系統性文獻回顧（詳見「四、國內外相關之文獻探討」之第零部分）歸納出四個研究缺口。首先，AI 主播與 AI 代理人的研究多以平台資料或問卷檢驗「是否有效」(Y. Liu et al., 2025; Yuan et al., 2025; Chen et al., 2026; Xiao et al., 2025; Zhou & Li, 2025)，**幾乎沒有研究從消費者的價值結構回答「為什麼」接受或排斥 AI 主播**；方法目的鏈在數位商務的應用也缺乏一致的分析程序 (Kilwinger & van Dam, 2021)。此為本研究可介入探討的第一缺口。')
    d.p('其次，直播研究的依變數多停留在購買意圖或銷售量 (Gu et al., 2024; H. Liu et al., 2025; Gong et al., 2025)。少數研究已證實即時互動會提高退貨 (Feng et al., 2025)、降低購後滿意 (Fan et al., 2025)，主播講解時間較長的商品退貨率較低 (Hu, 2027)，AI 助理則能降低退貨 (Wang et al., 2025)；但**「AI 主播 vs. 真人主播」對後悔、退貨與再購等購後結果的影響，仍缺乏因果證據**。此為本研究可介入探討的第二缺口。')
    d.p('第三，Luo et al. (2019) 的田野實驗顯示，在對話開始前揭露聊天機器人身分，會使購買率下降逾 79.7%；Brüns & Meißner (2024) 與 Kirk & Givi (2025) 發現，揭露 AI 撰寫內容會降低真實性與口碑；Gnewuch et al. (2024) 發現，揭露人類參與也會改變顧客的溝通方式。但 De Cicco et al. (2024) 發現，揭露虛擬網紅的合成身分並不影響品牌知覺；T. Li et al. (2025) 則發現，在服務開始前揭露聊天機器人身分反而提高失誤容忍度。Meng (2026) 的治理研究亦指出 AI 主播的消費者保護問題。**揭露效果的證據並不一致，而直播情境中「如何揭露」AI 主播身分，對信任與購買的影響仍未被檢驗。**此為本研究可介入探討的第三缺口。')
    d.p('最後，近期 AI 主播研究的樣本多來自中國大陸的平台或消費者 (Xiao et al., 2025; H. Liu et al., 2025; Meng, 2026)，且多為單一品類、單一方法。**以跨品類、多方法的設計，在台灣市場檢驗上述問題，並把結果轉譯為中小企業可用的決策工具，是本研究可介入探討的第四缺口。**有鑑於此，本研究以「誰來賣、怎麼說、買了會不會退」為核心問題意識，規劃二年三階段的研究計畫。')

    d.h4('研究計劃各階段問題與目的')
    d.p('本計畫研究架構共分為三個部分，分二年三個階段進行。第一階段（2027.08–2028.01，量表發展延至 2028.03）採質化方法，以軟式階梯訪談探索消費者向 AI 虛擬主播與真人主播購買的「屬性－後果－價值」結構，並發展價值傾向量表。接著，第二階段（2028.02–2028.10）以第一階段的價值鏈撰寫實驗話術，以 2×2×2 跨品類實驗與 AI 身分揭露實驗，檢驗主播類型、話術與產品類型對購買及購後預期的因果效果。')
    d.p('第三階段（2028.06–2029.04）則以真實直播購買者的調查與三個月退貨追蹤，建構購後路徑模型，並以多群組 SEM 比較不同主播類型與價值傾向的消費者。三個階段使研究脈絡由第一年的「價值發現」、「因果檢驗」推進至第二年的「模型推廣」，並共用同一品類庫與共同量表，形成完整且遞進的研究邏輯。')

    d.h4('研究計劃各階段主題與層次脈絡')
    d.p('本計畫將於第二年完成研究，綜整三個階段的結果，比較各方法在解釋上的獨特性，並轉譯為中小企業可用的決策工具。關於二年三階段研究計畫之主題、層次脈絡、研究方法與理論基礎，整理如表 1。')
    d.table('表 1　二年三階段研究計畫層次脈絡、研究問題、主題、研究方法及研究理論列表',
            [1300, 700, 1900, 1850, 1900, 1988],
            [['研究階段\n與時程', '層次\n脈絡', '研究問題', '主題', '研究方法', '研究理論基礎'],
             [dict(t='第一階段\n2027.08–2028.01\n（量表發展至 2028.03）', c=True), dict(t='初步\n發現', c=True), '消費者為什麼向 AI 主播或真人主播購買？', 'AI 虛擬主播與真人主播的消費者價值鏈：方法目的鏈探索', 'MEC 軟式階梯訪談\n人工內容分析、涵意矩陣、階梯價值圖', 'MEC 理論\n消費價值理論'],
             [dict(t='第二階段\n2028.02–2028.10', c=True), dict(t='深入\n檢驗', c=True), '什麼樣的主播配上什麼樣的話術最有效、最少退貨？', '主播類型 × 價值訴求話術 × 產品類型，以及 AI 身分揭露', '2×2×2 受試者間實驗\n單因子揭露實驗\n一週後追蹤', '社會知覺（溫暖與能力）\n說服知識模型\n後悔理論'],
             [dict(t='第三階段\n2028.06–2029.04', c=True), dict(t='推廣\n驗證', c=True), '從主播知覺到購後結果的路徑對誰成立？', '直播購物的購後路徑：信任、期望確認、滿意與退貨', 'SEM\n多群組 SEM、測量恆等性\n三個月退貨追蹤', '期望確認理論\n信任理論\n社會知覺理論']],
            center_cols=(1,))
    d.p('**本計畫透過此三階段、跨方法、跨品類的整合研究設計，回應直播電商「從當下轉換走向購後價值」的關鍵議題。**本計畫以經典方法回答 AI 主播的「為什麼」、「是否有因果」與「對誰成立」，有助於學術社群、平台與中小企業在導入 AI 主播時，同時考量銷售、退貨與消費者信任。')

    d.h2('二、研究計畫之目的')
    d.p('本研究規劃整體研究架構，以系統性的思維考量各階段的從屬性及關聯性。**本研究旨在以方法目的鏈、實驗設計與結構方程模式，系統性比較 AI 虛擬主播與真人主播的說服機制與購後後果。**首先，以軟式階梯訪談探索兩類主播購買者的價值鏈，並發展價值傾向量表。其次，以跨品類實驗檢驗主播類型、價值訴求話術與產品類型的交互作用，以及說服意圖知覺對購後後悔與退貨意圖的中介效果，並檢驗 AI 身分揭露方式的影響。最後，以真實購買者的調查與退貨追蹤建構購後路徑模型，並以多群組 SEM 比較不同主播類型與價值傾向的消費者，將結果轉譯為中小企業的「主播類型 × 話術 × 品類」決策表與揭露指引。')

    d.h2('三、研究計畫之原創性、重要性與預期影響性')
    d.h3('(一) 本研究之原創性方面：')
    d.p('本研究之原創性在「研究問題」、「理論整合」與「研究設計」三個層面。首先，在研究問題上，本研究**把 AI 主播的評估標準由「當下轉換」延伸到「購後後悔、退貨與再購」**，並提出「AI 主播因說服意圖知覺較低而減少退貨」的新假說。其次，在理論整合上，本研究結合方法目的鏈、社會知覺、說服知識與期望確認理論，以「第一階段的價值鏈是第二階段的話術、第一階段的量表是第三階段的分組」串連三個研究。第三，在研究設計上，本研究以消費者價值結構為基礎設計實驗話術，取代研究者自行設定的訊息類型，並以預先註冊、刺激抽樣與測量恆等性確保結論的效度 (Nosek et al., 2018; Wells & Windschitl, 1999)。')
    d.h3('(二) 本研究之重要性、預期影響性方面：')
    d.p('本研究之重要性，學術上，補足 AI 主播研究對「為什麼」、「購後結果」與「揭露方式」缺乏系統性探討的缺口，三個階段各自形成可投稿國際期刊的貢獻；實務上，研究結果可協助平台與品牌判斷在哪些品類、搭配哪種話術時採用 AI 主播，兼顧銷售與退貨成本。本研究之預期影響性，在學術層面，建立 AI 與真人銷售代理的比較架構；在實務層面，提供資源受限的中小企業低成本的主播與話術決策工具 (Wang & Zhang, 2025)；在社會層面，以 AI 主播揭露指引回應消費者保護議題 (Meng, 2026; Martin & Murphy, 2017)，並以降低退貨減少逆向物流。本計畫與五大研究主題之對應如表 2。')
    d.table('表 2　本計畫與五大研究主題之對應',
            [2400, 1700, 5538],
            [['研究主題', '在計畫中的角色', '對應內容'],
             ['主題一　創新發展', dict(t='研究情境', c=True), 'AI 虛擬主播、直播電商、生成式 AI 內容'],
             ['主題二　消費者心理行為', dict(t='依變數與中介機制', c=True), '終極價值、溫暖與能力知覺、說服意圖知覺、信任、後悔與滿意'],
             ['主題三　電子商務模式', dict(t='商業結果', c=True), '直播轉換、退貨、再購與退貨政策'],
             ['主題四　研究潛力', dict(t='研究方法', c=True), 'MEC、實驗設計與 SEM 的三方法整合；AI 銷售代理的效果評估'],
             ['主題五　電商市場發展需求', dict(t='實務轉譯', c=True), '中小企業主播與話術決策表、AI 主播揭露與退貨溝通指引']])

